using UnityEngine;
using System.Collections.Generic;

/// <summary>
/// 角色属性数据
/// </summary>
[System.Serializable]
public class CharacterStats
{
    public string characterName;
    public int maxHP;
    public int currentHP;
    public int attack;
    public int defense;
    public int speed;
    public int level;

    public bool IsAlive => currentHP > 0;

    public void TakeDamage(int damage)
    {
        int actualDamage = Mathf.Max(1, damage - defense);
        currentHP = Mathf.Max(0, currentHP - actualDamage);
    }

    public void Heal(int amount)
    {
        currentHP = Mathf.Min(maxHP, currentHP + amount);
    }
}

/// <summary>
/// 技能定义
/// </summary>
[System.Serializable]
public class SkillData
{
    public string skillName;
    public string description;
    public int mpCost;
    public int power;
    public SkillType type;
    public SkillTarget target;
}

public enum SkillType { Attack, Heal, Buff, Debuff }
public enum SkillTarget { SingleEnemy, AllEnemies, SingleAlly, AllAllies, Self }

/// <summary>
/// 角色控制器
/// 挂载: 角色GameObject
/// </summary>
public class CharacterStatsController : MonoBehaviour
{
    [SerializeField] private CharacterStats stats;
    [SerializeField] private List<SkillData> skills = new List<SkillData>();

    private int currentMP;

    public CharacterStats Stats => stats;
    public List<SkillData> Skills => skills;
    public int CurrentMP => currentMP;
    public bool IsAlive => stats != null && stats.IsAlive;

    public void Initialize(string name, int hp, int atk, int def, int spd)
    {
        stats = new CharacterStats
        {
            characterName = name,
            maxHP = hp,
            currentHP = hp,
            attack = atk,
            defense = def,
            speed = spd,
            level = 1
        };
        currentMP = 50;
    }

    public void UseSkill(SkillData skill, CharacterStatsController target)
    {
        if (currentMP < skill.mpCost) return;
        currentMP -= skill.mpCost;

        switch (skill.type)
        {
            case SkillType.Attack:
                int damage = stats.attack + skill.power;
                target.stats.TakeDamage(damage);
                break;
            case SkillType.Heal:
                target.stats.Heal(skill.power);
                break;
        }
    }

    public void BasicAttack(CharacterStatsController target)
    {
        target.stats.TakeDamage(stats.attack);
    }
}

