using UnityEngine;

/// <summary>
/// 战斗单位 - 战斗中的角色表示
/// </summary>
public class BattleUnit : MonoBehaviour
{
    [SerializeField] private CharacterStatsController statsController;
    [SerializeField] private bool isPlayer;

    public CharacterStatsController StatsController => statsController;
    public bool IsPlayer => isPlayer;
    public bool IsAlive => statsController != null && statsController.IsAlive;

    private SpriteRenderer spriteRenderer;
    private Vector3 originalPosition;
    private Color originalColor;

    private void Awake()
    {
        spriteRenderer = GetComponent<SpriteRenderer>();
        originalPosition = transform.position;
        if (spriteRenderer != null)
            originalColor = spriteRenderer.color;
    }

    public void Initialize(CharacterStatsController stats, bool player)
    {
        statsController = stats;
        isPlayer = player;
    }

    public void PlayAttackAnimation()
    {
        StartCoroutine(AttackAnim());
    }

    private System.Collections.IEnumerator AttackAnim()
    {
        Vector3 targetPos = originalPosition + (isPlayer ? Vector3.right : Vector3.left) * 1f;
        float t = 0;
        while (t < 0.15f)
        {
            t += Time.deltaTime;
            transform.position = Vector3.Lerp(originalPosition, targetPos, t / 0.15f);
            yield return null;
        }
        t = 0;
        while (t < 0.15f)
        {
            t += Time.deltaTime;
            transform.position = Vector3.Lerp(targetPos, originalPosition, t / 0.15f);
            yield return null;
        }
        transform.position = originalPosition;
    }

    public void PlayDamageAnimation()
    {
        StartCoroutine(DamageFlash());
    }

    private System.Collections.IEnumerator DamageFlash()
    {
        if (spriteRenderer == null) yield break;
        spriteRenderer.color = Color.red;
        yield return new WaitForSeconds(0.2f);
        spriteRenderer.color = originalColor;
    }

    public void PlayDeathAnimation()
    {
        StartCoroutine(DeathAnim());
    }

    private System.Collections.IEnumerator DeathAnim()
    {
        float t = 0;
        while (t < 0.5f)
        {
            t += Time.deltaTime;
            float alpha = 1f - (t / 0.5f);
            if (spriteRenderer != null)
            {
                Color c = originalColor;
                c.a = alpha;
                spriteRenderer.color = c;
            }
            yield return null;
        }
        gameObject.SetActive(false);
    }
}

