using UnityEngine;
using System.Collections;
using System.Collections.Generic;
using System.Linq;

/// <summary>
/// 回合制战斗管理器
/// 挂载: BattleManager
/// </summary>
public class BattleManager : MonoBehaviour
{
    public enum BattleState { Start, PlayerTurn, EnemyTurn, Won, Lost }

    [Header("战斗单位")]
    [SerializeField] private List<BattleUnit> playerUnits = new List<BattleUnit>();
    [SerializeField] private List<BattleUnit> enemyUnits = new List<BattleUnit>();

    [Header("设置")]
    [SerializeField] private float turnDelay = 0.5f;

    private BattleState currentState;
    private int currentTurnIndex;
    private List<BattleUnit> turnOrder = new List<BattleUnit>();

    public BattleState CurrentState => currentState;
    public List<BattleUnit> PlayerUnits => playerUnits;
    public List<BattleUnit> EnemyUnits => enemyUnits;

    public event System.Action<BattleState> OnBattleStateChanged;
    public event System.Action<BattleUnit, SkillData, BattleUnit> OnSkillUsed;
    public event System.Action<string> OnBattleMessage;
    public event System.Action<BattleUnit> OnTurnStarted;

    private void Start()
    {
        StartBattle();
    }

    public void StartBattle()
    {
        currentState = BattleState.Start;
        StartCoroutine(BattleStartSequence());
    }

    private IEnumerator BattleStartSequence()
    {
        yield return new WaitForSeconds(turnDelay);
        NextTurn();
    }

    private void NextTurn()
    {
        // 检查胜负
        if (enemyUnits.All(u => !u.IsAlive))
        {
            SetState(BattleState.Won);
            OnBattleMessage?.Invoke("战斗胜利！");
            return;
        }
        if (playerUnits.All(u => !u.IsAlive))
        {
            SetState(BattleState.Lost);
            OnBattleMessage?.Invoke("战斗失败...");
            return;
        }

        // 按速度排序所有存活单位
        turnOrder = playerUnits.Concat(enemyUnits)
            .Where(u => u.IsAlive)
            .OrderByDescending(u => u.StatsController.Stats.speed)
            .ToList();

        currentTurnIndex = 0;
        ProcessCurrentTurn();
    }

    private void ProcessCurrentTurn()
    {
        if (currentTurnIndex >= turnOrder.Count)
        {
            NextTurn();
            return;
        }

        BattleUnit current = turnOrder[currentTurnIndex];
        if (!current.IsAlive)
        {
            currentTurnIndex++;
            ProcessCurrentTurn();
            return;
        }

        OnTurnStarted?.Invoke(current);

        if (current.IsPlayer)
        {
            SetState(BattleState.PlayerTurn);
            // 等待玩家操作（由BattleUI处理）
        }
        else
        {
            SetState(BattleState.EnemyTurn);
            StartCoroutine(EnemyTurnRoutine(current));
        }
    }

    private IEnumerator EnemyTurnRoutine(BattleUnit enemy)
    {
        yield return new WaitForSeconds(0.8f);

        // 简单AI：随机攻击一个存活的玩家单位
        var alivePlayers = playerUnits.Where(u => u.IsAlive).ToList();
        if (alivePlayers.Count > 0)
        {
            BattleUnit target = alivePlayers[Random.Range(0, alivePlayers.Count)];
            PerformBasicAttack(enemy, target);
        }

        yield return new WaitForSeconds(turnDelay);
        AdvanceTurn();
    }

    public void PlayerUseSkill(int skillIndex, BattleUnit target)
    {
        if (currentState != BattleState.PlayerTurn) return;

        BattleUnit current = turnOrder[currentTurnIndex];
        var skills = current.StatsController.Skills;

        if (skillIndex >= 0 && skillIndex < skills.Count)
        {
            SkillData skill = skills[skillIndex];
            current.StatsController.UseSkill(skill, target.StatsController);
            current.PlayAttackAnimation();
            target.PlayDamageAnimation();
            OnSkillUsed?.Invoke(current, skill, target);
            OnBattleMessage?.Invoke($"{current.StatsController.Stats.characterName} 使用了 {skill.skillName}！");
        }

        AdvanceTurn();
    }

    public void PlayerBasicAttack(BattleUnit target)
    {
        if (currentState != BattleState.PlayerTurn) return;
        BattleUnit current = turnOrder[currentTurnIndex];
        PerformBasicAttack(current, target);
        AdvanceTurn();
    }

    private void PerformBasicAttack(BattleUnit attacker, BattleUnit target)
    {
        attacker.StatsController.BasicAttack(target.StatsController);
        attacker.PlayAttackAnimation();
        target.PlayDamageAnimation();

        if (!target.IsAlive)
            target.PlayDeathAnimation();

        string attackerName = attacker.StatsController.Stats.characterName;
        string targetName = target.StatsController.Stats.characterName;
        OnBattleMessage?.Invoke($"{attackerName} 攻击了 {targetName}！");
    }

    private void AdvanceTurn()
    {
        currentTurnIndex++;
        StartCoroutine(TurnAdvanceDelay());
    }

    private IEnumerator TurnAdvanceDelay()
    {
        yield return new WaitForSeconds(turnDelay);
        ProcessCurrentTurn();
    }

    private void SetState(BattleState state)
    {
        currentState = state;
        OnBattleStateChanged?.Invoke(state);
    }
}

