using UnityEngine;
using UnityEngine.UI;
using System.Collections.Generic;

/// <summary>
/// 战斗UI
/// 挂载: Canvas
/// </summary>
public class BattleUI : MonoBehaviour
{
    [Header("玩家UI")]
    [SerializeField] private Text playerNameText;
    [SerializeField] private Slider playerHPSlider;
    [SerializeField] private Text playerHPText;

    [Header("敌人UI")]
    [SerializeField] private Text enemyNameText;
    [SerializeField] private Slider enemyHPSlider;
    [SerializeField] private Text enemyHPText;

    [Header("操作")]
    [SerializeField] private Transform skillButtonContainer;
    [SerializeField] private GameObject skillButtonPrefab;
    [SerializeField] private Button attackButton;

    [Header("信息")]
    [SerializeField] private Text messageText;
    [SerializeField] private GameObject resultPanel;
    [SerializeField] private Text resultText;

    private BattleManager battleManager;
    private BattleUnit selectedTarget;
    private List<GameObject> skillButtons = new List<GameObject>();

    private void Start()
    {
        battleManager = FindFirstObjectByType<BattleManager>();
        if (battleManager == null) return;

        battleManager.OnBattleStateChanged += HandleStateChanged;
        battleManager.OnBattleMessage += msg => { if (messageText) messageText.text = msg; };
        battleManager.OnTurnStarted += HandleTurnStarted;

        if (attackButton != null)
            attackButton.onClick.AddListener(OnAttackClicked);

        if (resultPanel) resultPanel.SetActive(false);
    }

    private void HandleTurnStarted(BattleUnit unit)
    {
        UpdateHP();
        if (unit.IsPlayer)
            ShowPlayerActions(unit);
        else
            SetButtonsInteractable(false);
    }

    private void ShowPlayerActions(BattleUnit unit)
    {
        SetButtonsInteractable(true);
        ClearSkillButtons();

        var skills = unit.StatsController.Skills;
        for (int i = 0; i < skills.Count; i++)
        {
            int idx = i;
            SkillData skill = skills[i];
            if (skillButtonPrefab != null && skillButtonContainer != null)
            {
                GameObject btn = Instantiate(skillButtonPrefab, skillButtonContainer);
                btn.GetComponentInChildren<Text>().text = $"{skill.skillName} ({skill.mpCost}MP)";
                btn.GetComponent<Button>().onClick.AddListener(() => OnSkillClicked(idx));
                skillButtons.Add(btn);
            }
        }
    }

    private void ClearSkillButtons()
    {
        foreach (var btn in skillButtons)
            Destroy(btn);
        skillButtons.Clear();
    }

    private void OnAttackClicked()
    {
        var target = GetFirstAliveEnemy();
        if (target != null)
        {
            battleManager.PlayerBasicAttack(target);
            UpdateHP();
        }
    }

    private void OnSkillClicked(int index)
    {
        var target = GetFirstAliveEnemy();
        if (target != null)
        {
            battleManager.PlayerUseSkill(index, target);
            UpdateHP();
        }
    }

    private BattleUnit GetFirstAliveEnemy()
    {
        foreach (var u in battleManager.EnemyUnits)
            if (u.IsAlive) return u;
        return null;
    }

    private void HandleStateChanged(BattleManager.BattleState state)
    {
        UpdateHP();
        if (state == BattleManager.BattleState.Won || state == BattleManager.BattleState.Lost)
        {
            if (resultPanel) resultPanel.SetActive(true);
            if (resultText) resultText.text = state == BattleManager.BattleState.Won ? "胜利！" : "失败...";
            SetButtonsInteractable(false);
        }
    }

    private void UpdateHP()
    {
        if (battleManager.PlayerUnits.Count > 0)
        {
            var u = battleManager.PlayerUnits[0];
            var s = u.StatsController.Stats;
            if (playerNameText) playerNameText.text = s.characterName;
            if (playerHPSlider) playerHPSlider.value = (float)s.currentHP / s.maxHP;
            if (playerHPText) playerHPText.text = $"{s.currentHP}/{s.maxHP}";
        }
        if (battleManager.EnemyUnits.Count > 0)
        {
            var u = battleManager.EnemyUnits[0];
            var s = u.StatsController.Stats;
            if (enemyNameText) enemyNameText.text = s.characterName;
            if (enemyHPSlider) enemyHPSlider.value = (float)s.currentHP / s.maxHP;
            if (enemyHPText) enemyHPText.text = $"{s.currentHP}/{s.maxHP}";
        }
    }

    private void SetButtonsInteractable(bool interactable)
    {
        if (attackButton) attackButton.interactable = interactable;
        foreach (var btn in skillButtons)
        {
            var b = btn.GetComponent<Button>();
            if (b) b.interactable = interactable;
        }
    }
}

